import subprocess, json

def test_key(k):
    p = subprocess.Popen(["./executable"], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    out, _ = p.communicate(input=json.dumps({k: 1}).encode("utf-8"))
    line = out.decode("utf-8").strip().split("\n")[1]
    return line.startswith("json.")

test_chars = [chr(i) for i in range(128)] + ["å", "α", "中文", "😀", "1", "a", "_", "$", "-"]
for c in test_chars:
    valid = test_key(f"a{c}b")
    first_valid = test_key(f"{c}ab")
    print(f"Char {repr(c):6}: first={first_valid}, middle={valid}")
'"}

