import subprocess

code = """package main
import (
	"fmt"
	"os"
	"syscall"
	"unsafe"
)

func isTTY(f *os.File) bool {
	var termios syscall.Termios
	_, _, err := syscall.Syscall6(syscall.SYS_IOCTL, f.Fd(), uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&termios)), 0, 0, 0)
	return err == 0
}

func main() {
	fmt.Println("stdout is tty:", isTTY(os.Stdout))
}
"""

with open("/tmp/test_tty.go", "w") as f:
    f.write(code)

out = subprocess.check_output(["go", "run", "/tmp/test_tty.go"], text=True)
print(out)
'"}

