import subprocess

code = """package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"strings"
)

type PathToken struct {
	Str string
	Int int
	IsInt bool
}

func parseJSON(r io.Reader) {
	dec := json.NewDecoder(r)
	dec.UseNumber()

	// Recursive token parser
	var parseVal func(path []PathToken) error
	parseVal = func(path []PathToken) error {
		t, err := dec.Token()
		if err != nil {
			return err
		}

		switch v := t.(type) {
		case json.Delim:
			if v == '{' {
				// Object start
				fmt.Printf("path %v = {}\n", path)
				for dec.More() {
					keyToken, err := dec.Token()
					if err != nil {
						return err
					}
					key := keyToken.(string)
					newPath := append(append([]PathToken{}, path...), PathToken{Str: key, IsInt: false})
					if err := parseVal(newPath); err != nil {
						return err
					}
				}
				// consume '}'
				_, err := dec.Token()
				return err
			} else if v == '[' {
				// Array start
				fmt.Printf("path %v = []\n", path)
				idx := 0
				for dec.More() {
					newPath := append(append([]PathToken{}, path...), PathToken{Int: idx, IsInt: true})
					if err := parseVal(newPath); err != nil {
						return err
					}
					idx++
				}
				// consume ']'
				_, err := dec.Token()
				return err
			}
		default:
			// Primitive
			b, _ := json.Marshal(v)
			fmt.Printf("path %v = %s\n", path, string(b))
		}
		return nil
	}

	parseVal(nil)
}

func main() {
	input := `{"c": 3, "a": [10, 20], "b": {"y": 1, "x": 2}}`
	parseJSON(strings.NewReader(input))
}
"""

with open("/tmp/test_tokens.go", "w") as f:
    f.write(code)

out = subprocess.check_output(["go", "run", "/tmp/test_tokens.go"], text=True)
print(out)
'"}

