type Pair struct {
	Key string
	Val interface{}
}

type Object []Pair

func parseValue(dec *json.Decoder) (interface{}, error) {
	t, err := dec.Token()
	if err != nil {
		return nil, err
	}
	switch v := t.(type) {
	case json.Delim:
		if v == '{' {
			var obj Object
			for dec.More() {
				kt, err := dec.Token()
				if err != nil {
					return nil, err
				}
				key := kt.(string)
				val, err := parseValue(dec)
				if err != nil {
					return nil, err
				}
				obj = append(obj, Pair{Key: key, Val: val})
			}
			// consume '}'
			_, err := dec.Token()
			return obj, err
		} else if v == '[' {
			var arr []interface{}
			for dec.More() {
				val, err := parseValue(dec)
				if err != nil {
					return nil, err
				}
				arr = append(arr, val)
			}
			// consume ']'
			_, err := dec.Token()
			return arr, err
		}
	default:
		return v, nil
	}
	return nil, nil
}

