}

func isDigitStart(ch byte) bool {
	return ch >= '0' && ch <= '9'
}

func isNumChar(ch byte) bool {
	return (ch >= '0' && ch <= '9') || ch == '.' || ch == 'e' || ch == 'E' || ch == '+' || ch == '-'
}

