{"command":"cat << 'EOF' > gron.go
package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"sort"
	"strconv"
	"unicode"
)

type Token struct {
	Key     string
	Index   int
	IsIndex bool
}

type Statement struct {
	Path     []Token
	Value    string
	ValType  string // "obj", "arr", "str", "num", "bool", "null"
	RawValue interface{}
}

type Statements []Statement

func (s Statements) Len() int      { return len(s) }
func (s Statements) Swap(i, j int) { s[i], s[j] = s[j], s[i] }

func (s Statements) Less(i, j int) bool {
	p1, p2 := s[i].Path, s[j].Path
	minLen := len(p1)
	if len(p2) < minLen {
		minLen = len(p2)
	}
	for k := 0; k < minLen; k++ {
		t1, t2 := p1[k], p2[k]
		if t1.IsIndex && t2.IsIndex {
			if t1.Index != t2.Index {
				return t1.Index < t2.Index
			}
		} else if !t1.IsIndex && !t2.IsIndex {
			if t1.Key != t2.Key {
				return t1.Key < t2.Key
			}
		} else {
			s1 := formatTokenString(t1)
			s2 := formatTokenString(t2)
			if s1 != s2 {
				return s1 < s2
			}
		}
	}
	if len(p1) != len(p2) {
		return len(p1) < len(p2)
	}
	return s[i].Value < s[j].Value
}

func formatTokenString(t Token) string {
	if t.IsIndex {
		return "[" + strconv.Itoa(t.Index) + "]"
	}
	if validIdentifier(t.Key) {
		return "." + t.Key
	}
	b, _ := jsonMarshal(t.Key)
	return "[" + string(b) + "]"
}

func validIdentifier(s string) bool {
	if s == "" {
		return false
	}
	switch s {
	case "break", "case", "catch", "class", "const", "continue", "debugger", "default", "delete", "do", "else", "export", "extends", "false", "finally", "for", "function", "if", "import", "in", "instanceof", "new", "null", "return", "super", "switch", "this", "throw", "true", "try", "typeof", "var", "void", "while", "with", "yield":
		return false
	}
	for i, r := range s {
		if i == 0 {
			if !unicode.IsLetter(r) && r != '_' && r != '$' {
				return false
			}
		} else {
			if !unicode.IsLetter(r) && !unicode.IsDigit(r) && r != '_' && r != '$' {
				return false
			}
		}
	}
	return true
}

func jsonMarshal(v interface{}) ([]byte, error) {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	err := enc.Encode(v)
	if err != nil {
		return nil, err
	}
	b := buf.Bytes()
	if len(b) > 0 && b[len(b)-1] == '\n' {
		b = b[:len(b)-1]
	}
	return b, nil
}

type Pair struct {
	Key string
	Val interface{}
}
type Object []Pair

func parseValue(dec *json.Decoder) (interface{}, error) {
	t, err := dec.Token()
	if err != nil {
		return nil, err
	}
	switch v := t.(type) {
	case json.Delim:
		if v == '{' {
			var obj Object
			for dec.More() {
				kt, err := dec.Token()
				if err != nil {
					return nil, err
				}
				key, ok := kt.(string)
				if !ok {
					return nil, fmt.Errorf("expected string key")
				}
				val, err := parseValue(dec)
				if err != nil {
					return nil, err
				}
				obj = append(obj, Pair{Key: key, Val: val})
			}
			// consume '}'
			_, err := dec.Token()
			return obj, err
		} else if v == '[' {
			var arr []interface{}
			for dec.More() {
				val, err := parseValue(dec)
				if err != nil {
					return nil, err
				}
				arr = append(arr, val)
			}
			// consume ']'
			_, err := dec.Token()
			return arr, err
		}
	default:
		return v, nil
	}
	return nil, nil
}

func buildStatements(val interface{}, path []Token, stmts *Statements) {
	switch v := val.(type) {
	case Object:
		*stmts = append(*stmts, Statement{
			Path:     path,
			Value:    "{}",
			ValType:  "obj",
			RawValue: map[string]interface{}{},
		})
