{"command":"cat << 'EOF' > ungron.go
package main

import (
	"bufio"
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"strconv"
	"strings"
	"unicode"
)

type ParsedStmt struct {
	Path  []Token
	Value interface{}
	IsRaw bool // whether value is raw string or parsed
}

func parseGronLine(line string) ([]Token, interface{}, error) {
	line = strings.TrimSpace(line)
	if line == "" {
		return nil, nil, nil
	}
	if !strings.HasSuffix(line, ";") {
		return nil, nil, fmt.Errorf("statement has no value")
	}
	line = strings.TrimSuffix(line, ";")

	eqIdx := strings.Index(line, "=")
	if eqIdx == -1 {
		return nil, nil, fmt.Errorf("invalid statement")
	}

	lhs := strings.TrimSpace(line[:eqIdx])
	rhs := strings.TrimSpace(line[eqIdx+1:])

	if rhs == "" {
		return nil, nil, fmt.Errorf("statement has no value")
	}

	tokens, err := parsePathLHS(lhs)
	if err != nil {
		return nil, nil, err
	}

	var val interface{}
	if rhs == "{}" {
		val = Object{}
	} else if rhs == "[]" {
		val = []interface{}{}
	} else {
		err := json.Unmarshal([]byte(rhs), &val)
		if err != nil {
			return nil, nil, fmt.Errorf("invalid value `%s`", rhs)
		}
	}

	return tokens, val, nil
}

func parsePathLHS(lhs string) ([]Token, error) {
	if lhs == "" {
		return nil, fmt.Errorf("invalid statement")
	}

	var tokens []Token
	i := 0
	n := len(lhs)

	// First token
	if lhs[0] == '[' {
		// Bracket at start
		tok, nextI, err := parseBracketToken(lhs, 0)
		if err != nil {
			return nil, fmt.Errorf("invalid statement")
		}
		tokens = append(tokens, tok)
		i = nextI
	} else {
		// Bare identifier
		start := i
		for i < n && isAlphaChar(rune(lhs[i])) {
			i++
		}
		if i == start {
			return nil, fmt.Errorf("invalid statement")
		}
		tokKey := lhs[start:i]
		if !validIdentifier(tokKey) && tokKey != "json" {
			return nil, fmt.Errorf("invalid statement")
		}
		tokens = append(tokens, Token{Key: tokKey, IsIndex: false})
	}

	for i < n {
		if lhs[i] == '.' {
			i++
			start := i
			for i < n && isAlphaChar(rune(lhs[i])) {
				i++
			}
			if i == start {
				return nil, fmt.Errorf("invalid statement")
			}
			tokKey := lhs[start:i]
			if !validIdentifier(tokKey) {
				return nil, fmt.Errorf("invalid statement")
			}
			tokens = append(tokens, Token{Key: tokKey, IsIndex: false})
		} else if lhs[i] == '[' {
			tok, nextI, err := parseBracketToken(lhs, i)
			if err != nil {
				return nil, fmt.Errorf("invalid statement")
			}
			tokens = append(tokens, tok)
			i = nextI
		} else {
			return nil, fmt.Errorf("invalid statement")
		}
	}

	return tokens, nil
}

func parseBracketToken(s string, start int) (Token, int, error) {
	if start >= len(s) || s[start] != '[' {
		return Token{}, start, fmt.Errorf("expected [")
	}
	i := start + 1
	if i >= len(s) {
		return Token{}, start, fmt.Errorf("unclosed [")
	}

	if s[i] == '"' {
		// Parse string key inside brackets
		strStart := i
		i++
		for i < len(s) {
			if s[i] == '\\' && i+1 < len(s) {
				i += 2
				continue
			}
			if s[i] == '"' {
				i++
				break
			}
			i++
		}
		if i > len(s) || s[i-1] != '"' {
			return Token{}, start, fmt.Errorf("unclosed string key")
		}
		var keyStr string
		err := json.Unmarshal([]byte(s[strStart:i]), &keyStr)
		if err != nil {
			return Token{}, start, err
		}
		if i >= len(s) || s[i] != ']' {
			return Token{}, start, fmt.Errorf("expected ]")
		}
		return Token{Key: keyStr, IsIndex: false}, i + 1, nil
	} else {
		// Digits / integer index
		numStart := i
		for i < len(s) && unicode.IsDigit(rune(s[i])) {
			i++
		}
		if i == numStart {
			return Token{}, start, fmt.Errorf("expected digits")
		}
		idx, err := strconv.Atoi(s[numStart:i])
		if err != nil {
			return Token{}, start, err
		}
		if i >= len(s) || s[i] != ']' {
			return Token{}, start, fmt.Errorf("expected ]")
		}
		return Token{Index: idx, IsIndex: true}, i + 1, nil
	}
}

func ProcessValues(r io.Reader, w io.Writer) error {
	scanner := bufio.NewScanner(r)
	parsedAny := false
	for scanner.Scan() {
		line := scanner.Text()
		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			continue
		}
		_, val, err := parseGronLine(line)
		if err != nil {
			continue
		}
		parsedAny = true
		if val == nil {
			continue
		}
		switch v := val.(type) {
		case Object:
			// ignore empty object initialization
		case []interface{}:
			if len(v) == 0 {
				// ignore empty array initialization
			} else {
				b, _ := jsonMarshal(v)
				fmt.Fprintln(w, string(b))
			}
		case string:
			fmt.Fprintln(w, v)
		case bool:
			if v {
				fmt.Fprintln(w, "true")
			} else {
				fmt.Fprintln(w, "false")
			}
		case json.Number:
			fmt.Fprintln(w, string(v))
		case float64:
			b, _ := jsonMarshal(v)
			fmt.Fprintln(w, string(b))
		default:
			if v == nil {
				fmt.Fprintln(w, "null")
			} else {
				b, _ := jsonMarshal(v)
				fmt.Fprintln(w, string(b))
			}
		}
	}
	_ = parsedAny
	return nil
}

func ProcessUngron(r io.Reader, w io.Writer, isJSON, colorize bool) error {
	var root interface{}
	hasRoot := false

	if isJSON {
		dec := json.NewDecoder(r)
		for {
			var raw []interface{}
			err := dec.Decode(&raw)
			if err != nil {
				if err == io.EOF {
					break
				}
				return fmt.Errorf("failed to parse statements: %w", err)
			}
			if len(raw) != 2 {
				return fmt.Errorf("failed to parse statements: invalid json stream statement")
			}
			pathRaw, ok := raw[0].([]interface{})
			if !ok {
				return fmt.Errorf("failed to parse statements: invalid path array")
			}
			val := raw[1]

			var tokens []Token
			tokens = append(tokens, Token{Key: "json", IsIndex: false})
			for _, elem := range pathRaw {
				if k, ok := elem.(string); ok {
					tokens = append(tokens, Token{Key: k, IsIndex: false})
				} else if n, ok := elem.(float64); ok {
					tokens = append(tokens, Token{Index: int(n), IsIndex: true})
				} else if num, ok := elem.(json.Number); ok {
					i, _ := num.Int64()
					tokens = append(tokens, Token{Index: int(i), IsIndex: true})
				}
			}

			err = mergeStatement(&root, tokens, val, &hasRoot)
			if err != nil {
				return err
			}
		}
	} else {
		scanner := bufio.NewScanner(r)
		parsedCount := 0
		for scanner.Scan() {
			line := scanner.Text()
			if strings.TrimSpace(line) == "" {
				continue
			}
			tokens, val, err := parseGronLine(line)
			if err != nil {
				return fmt.Errorf("ungron failed for `%s`: %w", strings.TrimSpace(line), err)
			}
			parsedCount++
			err = mergeStatement(&root, tokens, val, &hasRoot)
			if err != nil {
				return err
			}
		}
		if parsedCount == 0 {
			return fmt.Errorf("no statements were parsed")
		}
	}

	if !hasRoot {
		return fmt.Errorf("no statements were parsed")
	}

	// Format root into JSON
	var jsonBytes []byte
	var err error

	if root == nil {
		jsonBytes = []byte("null")
	} else {
		jsonBytes, err = json.MarshalIndent(root, "", "  ")
		if err != nil {
			return fmt.Errorf("failed to encode JSON: %w", err)
		}
	}

	if colorize {
		jsonBytes = colorizeJSON(jsonBytes)
	}

	fmt.Fprintln(w, string(jsonBytes))
	return nil
}

func mergeStatement(root *interface{}, tokens []Token, val interface{}, hasRoot *bool) error {
	*hasRoot = true

	// Strip "json" prefix if len > 1
	path := tokens
	if len(path) > 0 && path[0].Key == "json" && !path[0].IsIndex {
		if len(path) > 1 {
			path = path[1:]
		} else {
			// Length 1: root assignment e.g. json = {}; or json = 1;
			if *root == nil {
				*root = val
			} else {
				// If root is already set
				if _, ok := val.(Object); ok {
					// json = {} on existing object, keep existing
				} else if _, ok := val.([]interface{}); ok {
					// json = [] on existing array, keep existing
				} else {
					*root = val
				}
			}
			return nil
		}
	}

	return mergeNode(root, path, val)
}

func mergeNode(target *interface{}, path []Token, val interface{}) error {
	if len(path) == 0 {
		*target = val
		return nil
	}

	t := path[0]

	if t.IsIndex {
		if *target == nil {
			*target = []interface{}{}
		}
		arr, ok := (*target).([]interface{})
		if !ok {
			return fmt.Errorf("failed to merge statements: cannot merge array with non-array")
		}
		for len(arr) <= t.Index {
			arr = append(arr, nil)
		}
		if len(path) == 1 {
			if _, isObj := val.(Object); isObj {
				if arr[t.Index] == nil {
					arr[t.Index] = Object{}
				}
			} else if _, isArr := val.([]interface{}); isArr {
				if arr[t.Index] == nil {
					arr[t.Index] = []interface{}{}
				}
			} else {
				arr[t.Index] = val
			}
		} else {
			if arr[t.Index] == nil {
				if path[1].IsIndex {
					arr[t.Index] = []interface{}{}
				} else {
					arr[t.Index] = Object{}
				}
			}
			err := mergeNode(&arr[t.Index], path[1:], val)
			if err != nil {
				return err
			}
		}
		*target = arr
		return nil
	} else {
		if *target == nil {
			*target = Object{}
		}
		var obj Object
		if o, ok := (*target).(Object); ok {
			obj = o
		} else if m, ok := (*target).(map[string]interface{}); ok {
			// Convert map to Object
			for k, v := range m {
				obj = append(obj, Pair{Key: k, Val: v})
			}
		} else {
			return fmt.Errorf("failed to merge statements: cannot merge object with non-object")
		}

		// Find key in obj
		idx := -1
		for i, p := range obj {
			if p.Key == t.Key {
				idx = i
				break
			}
		}

		if len(path) == 1 {
			if _, isObj := val.(Object); isObj {
				if idx == -1 {
					obj = append(obj, Pair{Key: t.Key, Val: Object{}})
				}
			} else if _, isArr := val.([]interface{}); isArr {
				if idx == -1 {
					obj = append(obj, Pair{Key: t.Key, Val: []interface{}{}})
				}
			} else {
				if idx == -1 {
					obj = append(obj, Pair{Key: t.Key, Val: val})
				} else {
					obj[idx].Val = val
				}
			}
		} else {
			if idx == -1 {
				var child interface{}
				if path[1].IsIndex {
					child = []interface{}{}
				} else {
					child = Object{}
				}
				err := mergeNode(&child, path[1:], val)
				if err != nil {
					return err
				}
				obj = append(obj, Pair{Key: t.Key, Val: child})
			} else {
				err := mergeNode(&obj[idx].Val, path[1:], val)
				if err != nil {
					return err
				}
			}
		}
		*target = obj
		return nil
	}
}

// MarshalJSON implementation for Object to preserve insertion order
func (o Object) MarshalJSON() ([]byte, error) {
	var buf bytes.Buffer
	buf.WriteByte('{')
	for i, pair := range o {
		if i > 0 {
			buf.WriteByte(',')
		}
		keyBytes, err := jsonMarshal(pair.Key)
		if err != nil {
			return nil, err
		}
		buf.Write(keyBytes)
		buf.WriteByte(':')
		valBytes, err := jsonMarshal(pair.Val)
		if err != nil {
			return nil, err
		}
		buf.Write(valBytes)
	}
	buf.WriteByte('}')
	return buf.Bytes(), nil
}
