{"command":"cat << 'EOF' > main.go
package main

import (
	"crypto/tls"
	"flag"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"strings"
	"syscall"
	"unsafe"
)

const versionString = "gron version dev"

const helpText = `Transform JSON (from a file, URL, or stdin) into discrete assignments to make it greppable

Usage:
  gron [OPTIONS] [FILE|URL|-]

Options:
  -u, --ungron     Reverse the operation (turn assignments back into JSON)
  -v, --values     Print just the values of provided assignments
  -c, --colorize   Colorize output (default on tty)
  -m, --monochrome Monochrome (don't colorize output)
  -s, --stream     Treat each line of input as a separate JSON object
  -k, --insecure   Disable certificate validation
  -x, --proxy      Set proxy configuration
      --noproxy    Comma-separated list of hosts for which not to use a proxy, if one is specified.
  -j, --json       Represent gron data as JSON stream
      --no-sort    Don't sort output (faster)
      --version    Print version information

Exit Codes:
  0	OK
  1	Failed to open file
  2	Failed to read input
  3	Failed to form statements
  4	Failed to fetch URL
  5	Failed to parse statements
  6	Failed to encode JSON

Examples:
  gron /tmp/apiresponse.json
  gron http://jsonplaceholder.typicode.com/users/1 
  curl -s http://jsonplaceholder.typicode.com/users/1 | gron
  gron http://jsonplaceholder.typicode.com/users/1 | grep company | gron --ungron
`

func isTTY(f *os.File) bool {
	var termios syscall.Termios
	_, _, err := syscall.Syscall6(syscall.SYS_IOCTL, f.Fd(), uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&termios)), 0, 0, 0)
	return err == 0
}

func main() {
	flags := flag.NewFlagSet("gron", flag.ContinueOnError)
	flags.SetOutput(os.Stderr)
	flags.Usage = func() {}

	ungron := flags.Bool("u", false, "")
	flags.BoolVar(ungron, "ungron", false, "")

	values := flags.Bool("v", false, "")
	flags.BoolVar(values, "values", false, "")

	colorize := flags.Bool("c", false, "")
	flags.BoolVar(colorize, "colorize", false, "")

	monochrome := flags.Bool("m", false, "")
	flags.BoolVar(monochrome, "monochrome", false, "")

	stream := flags.Bool("s", false, "")
	flags.BoolVar(stream, "stream", false, "")

	insecure := flags.Bool("k", false, "")
	flags.BoolVar(insecure, "insecure", false, "")

	proxy := flags.String("x", "", "")
	flags.StringVar(proxy, "proxy", "", "")

	noProxy := flags.String("noproxy", "", "")

	jsonStream := flags.Bool("j", false, "")
	flags.BoolVar(jsonStream, "json", false, "")

	noSort := flags.Bool("no-sort", false, "")

	versionFlag := flags.Bool("version", false, "")

	err := flags.Parse(os.Args[1:])
	if err != nil {
		if err == flag.ErrHelp {
			fmt.Fprint(os.Stderr, helpText)
			os.Exit(0)
		}
		fmt.Fprintf(os.Stderr, "%s\n", err)
		fmt.Fprint(os.Stderr, helpText)
		os.Exit(2)
	}

	if *versionFlag {
		fmt.Println(versionString)
		os.Exit(0)
	}

	// Colorization logic
	useColor := false
	if *colorize {
		useColor = true
	} else if *monochrome {
		useColor = false
	} else {
		useColor = isTTY(os.Stdout)
	}

	// Input source
	var r io.Reader
	var closeInput func()
	args := flags.Args()
	inputLocation := "-"
	if len(args) > 0 {
		inputLocation = args[0]
	}

	if inputLocation == "-" {
		r = os.Stdin
		closeInput = func() {}
	} else if strings.HasPrefix(inputLocation, "http://") || strings.HasPrefix(inputLocation, "https://") {
		req, err := http.NewRequest("GET", inputLocation, nil)
		if err != nil {
			fmt.Fprintf(os.Stderr, "%s\n", err)
			os.Exit(4)
		}
		req.Header.Set("User-Agent", "gron/dev")
		req.Header.Set("Accept", "application/json")

		tr := &http.Transport{}
		if *insecure {
			tr.TLSClientConfig = &tls.Config{InsecureSkipVerify: true}
		}

		proxyVal := *proxy
		noProxyVal := *noProxy
		if proxyVal != "" || noProxyVal != "" {
			tr.Proxy = func(req *http.Request) (*url.URL, error) {
				if noProxyVal != "" {
					hosts := strings.Split(noProxyVal, ",")
					reqHost := req.URL.Hostname()
					for _, h := range hosts {
						h = strings.TrimSpace(h)
						if h != "" && (reqHost == h || strings.HasSuffix(reqHost, "."+h)) {
							return nil, nil
						}
					}
				}
				if proxyVal != "" {
					u, err := url.Parse(proxyVal)
					if err != nil {
						return nil, err
					}
					return u, nil
				}
				return http.ProxyFromEnvironment(req)
			}
		} else {
			tr.Proxy = http.ProxyFromEnvironment
		}

		client := &http.Client{Transport: tr}
		resp, err := client.Do(req)
		if err != nil {
			fmt.Fprintf(os.Stderr, "%s\n", err)
			os.Exit(4)
		}
		r = resp.Body
		closeInput = func() { resp.Body.Close() }
	} else {
		f, err := os.Open(inputLocation)
		if err != nil {
			fmt.Fprintf(os.Stderr, "%s\n", err)
			os.Exit(1)
		}
		r = f
		closeInput = func() { f.Close() }
	}
	defer closeInput()

	if *values {
		err := ProcessValues(r, os.Stdout)
		if err != nil {
			fmt.Fprintf(os.Stderr, "%s\n", err)
			os.Exit(5)
		}
		os.Exit(0)
	}

	if *ungron {
		err := ProcessUngron(r, os.Stdout, *jsonStream, useColor)
		if err != nil {
			fmt.Fprintf(os.Stderr, "%s\n", err)
			os.Exit(5)
		}
		os.Exit(0)
	}

	err = ProcessGron(r, os.Stdout, *stream, *jsonStream, *noSort, useColor)
	if err != nil {
