	flags.BoolVar(ungron, "ungron", false, "")

	values := flags.Bool("v", false, "")
	flags.BoolVar(values, "values", false, "")

	colorize := flags.Bool("c", false, "")
	flags.BoolVar(colorize, "colorize", false, "")

	monochrome := flags.Bool("m", false, "")
	flags.BoolVar(monochrome, "monochrome", false, "")

	stream := flags.Bool("s", false, "")
	flags.BoolVar(stream, "stream", false, "")

	insecure := flags.Bool("k", false, "")
	flags.BoolVar(insecure, "insecure", false, "")

	proxy := flags.String("x", "", "")
	flags.StringVar(proxy, "proxy", "", "")

	noProxy := flags.String("noproxy", "", "")

	jsonStream := flags.Bool("j", false, "")
	flags.BoolVar(jsonStream, "json", false, "")

	noSort := flags.Bool("no-sort", false, "")

	versionFlag := flags.Bool("version", false, "")

	err := flags.Parse(os.Args[1:])
	if err != nil {
		if err == flag.ErrHelp {
			fmt.Fprint(os.Stderr, helpText)
			os.Exit(0)
		}
		fmt.Fprintf(os.Stderr, "%s\n", err)
		fmt.Fprint(os.Stderr, helpText)
		os.Exit(2)
	}

	if *versionFlag {
		fmt.Println(versionString)
		os.Exit(0)
	}

	// Colorization logic
	useColor := false
	if *colorize {
		useColor = true
	} else if *monochrome {
		useColor = false
	} else {
		useColor = isTTY(os.Stdout)
	}

