		noProxyVal := *noProxy
		if proxyVal != "" || noProxyVal != "" {
			tr.Proxy = func(req *http.Request) (*url.URL, error) {
				if noProxyVal != "" {
					hosts := strings.Split(noProxyVal, ",")
					reqHost := req.URL.Hostname()
					for _, h := range hosts {
						h = strings.TrimSpace(h)
						if h != "" && (reqHost == h || strings.HasSuffix(reqHost, "."+h)) {
							return nil, nil
						}
					}
				}
				if proxyVal != "" {
					u, err := url.Parse(proxyVal)
					if err != nil {
						return nil, err
					}
					return u, nil
				}
				return http.ProxyFromEnvironment(req)
			}
		} else {
			tr.Proxy = http.ProxyFromEnvironment
		}

		client := &http.Client{Transport: tr}
		resp, err := client.Do(req)
		if err != nil {
			fmt.Fprintf(os.Stderr, "%s\n", err)
			os.Exit(4)
		}
		r = resp.Body
		closeInput = func() { resp.Body.Close() }
	} else {
		f, err := os.Open(inputLocation)
		if err != nil {
			fmt.Fprintf(os.Stderr, "%s\n", err)
			os.Exit(1)
		}
		r = f
		closeInput = func() { f.Close() }
	}
	defer closeInput()

	if *values {
		err := ProcessValues(r, os.Stdout)
		if err != nil {
			fmt.Fprintf(os.Stderr, "%s\n", err)
			os.Exit(5)
		}
		os.Exit(0)
	}

	if *ungron {
		err := ProcessUngron(r, os.Stdout, *jsonStream, useColor)
		if err != nil {
			fmt.Fprintf(os.Stderr, "%s\n", err)
			os.Exit(5)
		}
		os.Exit(0)
	}

	err = ProcessGron(r, os.Stdout, *stream, *jsonStream, *noSort, useColor)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s\n", err)
		if strings.Contains(err.Error(), "failed to encode JSON") {
			os.Exit(6)
		}
		os.Exit(3)
	}
	os.Exit(0)
}
