{"command":"cat << 'EOF' > gron.go
package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"sort"
	"strconv"
	"unicode"
)

type Token struct {
	Key     string
	Index   int
	IsIndex bool
}

type Statement struct {
	Path     []Token
	Value    string
	ValType  string // "obj", "arr", "str", "num", "bool", "null"
	RawValue interface{}
}

type Statements []Statement

func (s Statements) Len() int      { return len(s) }
func (s Statements) Swap(i, j int) { s[i], s[j] = s[j], s[i] }

func (s Statements) Less(i, j int) bool {
	p1, p2 := s[i].Path, s[j].Path
	minLen := len(p1)
	if len(p2) < minLen {
		minLen = len(p2)
	}
	for k := 0; k < minLen; k++ {
		t1, t2 := p1[k], p2[k]
		if t1.IsIndex && t2.IsIndex {
			if t1.Index != t2.Index {
				return t1.Index < t2.Index
			}
		} else if !t1.IsIndex && !t2.IsIndex {
			if t1.Key != t2.Key {
				return t1.Key < t2.Key
			}
		} else {
			s1 := formatTokenString(t1, k == 0)
			s2 := formatTokenString(t2, k == 0)
			if s1 != s2 {
				return s1 < s2
			}
		}
	}
	if len(p1) != len(p2) {
		return len(p1) < len(p2)
	}
	return s[i].Value < s[j].Value
}

func formatTokenString(t Token, isFirst bool) string {
	if t.IsIndex {
		return "[" + strconv.Itoa(t.Index) + "]"
	}
	if isFirst {
		return t.Key
	}
	if validIdentifier(t.Key) {
		return "." + t.Key
	}
	b, _ := jsonMarshal(t.Key)
	return "[" + string(b) + "]"
}

func validIdentifier(s string) bool {
	if s == "" {
		return false
	}
	switch s {
	case "break", "case", "catch", "class", "const", "continue", "debugger", "default", "delete", "do", "else", "export", "extends", "false", "finally", "for", "function", "if", "import", "in", "instanceof", "new", "null", "return", "super", "switch", "this", "throw", "true", "try", "typeof", "var", "void", "while", "with", "yield":
		return false
	}
	for i, r := range s {
		if i == 0 {
			if !unicode.IsLetter(r) && r != '_' && r != '$' {
				return false
			}
		} else {
			if !unicode.IsLetter(r) && !unicode.IsDigit(r) && r != '_' && r != '$' {
				return false
			}
		}
	}
	return true
}

func jsonMarshal(v interface{}) ([]byte, error) {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	err := enc.Encode(v)
	if err != nil {
		return nil, err
	}
	b := buf.Bytes()
	if len(b) > 0 && b[len(b)-1] == '\n' {
		b = b[:len(b)-1]
	}
	return b, nil
}

type Pair struct {
	Key string
	Val interface{}
}
type Object []Pair

func parseValueOrdered(dec *json.Decoder) (interface{}, error) {
	t, err := dec.Token()
	if err != nil {
		return nil, err
	}
	switch v := t.(type) {
	case json.Delim:
		if v == '{' {
			var obj Object
			for dec.More() {
				kt, err := dec.Token()
				if err != nil {
					return nil, err
				}
				key, ok := kt.(string)
				if !ok {
					return nil, fmt.Errorf("expected string key")
				}
				val, err := parseValueOrdered(dec)
				if err != nil {
					return nil, err
				}
				obj = append(obj, Pair{Key: key, Val: val})
			}
			_, err := dec.Token()
			return obj, err
		} else if v == '[' {
			var arr []interface{}
			for dec.More() {
				val, err := parseValueOrdered(dec)
				if err != nil {
					return nil, err
				}
				arr = append(arr, val)
			}
			_, err := dec.Token()
			return arr, err
		}
	default:
		return v, nil
	}
	return nil, nil
}

func parseValueStandard(dec *json.Decoder) (interface{}, error) {
	var v interface{}
	err := dec.Decode(&v)
	return v, err
}

func buildStatements(val interface{}, path []Token, stmts *Statements) {
	switch v := val.(type) {
	case Object:
		*stmts = append(*stmts, Statement{
			Path:     path,
			Value:    "{}",
			ValType:  "obj",
			RawValue: map[string]interface{}{},
		})
		for _, pair := range v {
			childPath := append(append([]Token{}, path...), Token{Key: pair.Key, IsIndex: false})
			buildStatements(pair.Val, childPath, stmts)
		}
	case map[string]interface{}:
		*stmts = append(*stmts, Statement{
			Path:     path,
			Value:    "{}",
			ValType:  "obj",
			RawValue: v,
		})
		for k, elem := range v {
			childPath := append(append([]Token{}, path...), Token{Key: k, IsIndex: false})
			buildStatements(elem, childPath, stmts)
		}
	case []interface{}:
		*stmts = append(*stmts, Statement{
			Path:     path,
			Value:    "[]",
			ValType:  "arr",
			RawValue: v,
		})
		for i, elem := range v {
			childPath := append(append([]Token{}, path...), Token{Index: i, IsIndex: true})
			buildStatements(elem, childPath, stmts)
		}
	case string:
		b, _ := jsonMarshal(v)
		*stmts = append(*stmts, Statement{
			Path:     path,
			Value:    string(b),
			ValType:  "str",
			RawValue: v,
		})
	case json.Number:
		*stmts = append(*stmts, Statement{
			Path:     path,
			Value:    string(v),
			ValType:  "num",
			RawValue: v,
		})
	case float64:
		b, _ := jsonMarshal(v)
		*stmts = append(*stmts, Statement{
			Path:     path,
			Value:    string(b),
			ValType:  "num",
			RawValue: v,
		})
	case bool:
		valStr := "false"
		if v {
			valStr = "true"
		}
		*stmts = append(*stmts, Statement{
			Path:     path,
			Value:    valStr,
			ValType:  "bool",
			RawValue: v,
		})
	case nil:
		*stmts = append(*stmts, Statement{
			Path:     path,
			Value:    "null",
			ValType:  "null",
			RawValue: nil,
		})
	}
}

func ProcessGron(r io.Reader, w io.Writer, isStream, isJSON, noSort, colorize bool) error {
	dec := json.NewDecoder(r)
	dec.UseNumber()

	var stmts Statements

	if isStream {
		rootPath := []Token{{Key: "json", IsIndex: false}}
		stmts = append(stmts, Statement{
			Path:     rootPath,
			Value:    "[]",
			ValType:  "arr",
			RawValue: []interface{}{},
		})
		idx := 0
		for {
			var val interface{}
			var err error
			if noSort {
				val, err = parseValueOrdered(dec)
			} else {
				val, err = parseValueStandard(dec)
			}
			if err != nil {
				if err == io.EOF {
					if idx == 0 {
						return fmt.Errorf("failed to form statements: EOF")
					}
					break
				}
				return fmt.Errorf("failed to form statements: %w", err)
			}
			childPath := append(append([]Token{}, rootPath...), Token{Index: idx, IsIndex: true})
			buildStatements(val, childPath, &stmts)
			idx++
		}
	} else {
		var val interface{}
		var err error
		if noSort {
			val, err = parseValueOrdered(dec)
		} else {
			val, err = parseValueStandard(dec)
		}
		if err != nil {
			return fmt.Errorf("failed to form statements: %w", err)
		}
		rootPath := []Token{{Key: "json", IsIndex: false}}
		buildStatements(val, rootPath, &stmts)
	}

	if !noSort {
		sort.Stable(stmts)
	}

	if isJSON {
		for _, stmt := range stmts {
			var pathArr []interface{}
			for i, t := range stmt.Path {
				if i == 0 {
					continue // skip "json"
				}
				if t.IsIndex {
					pathArr = append(pathArr, t.Index)
				} else {
					pathArr = append(pathArr, t.Key)
				}
			}
			if pathArr == nil {
				pathArr = []interface{}{}
			}
			raw := stmt.RawValue
			if stmt.ValType == "obj" {
				raw = map[string]interface{}{}
			} else if stmt.ValType == "arr" {
				raw = []interface{}{}
			}
			lineBytes, err := jsonMarshal([]interface{}{pathArr, raw})
			if err != nil {
				return fmt.Errorf("failed to encode JSON: %w", err)
			}
			fmt.Fprintln(w, string(lineBytes))
		}
		return nil
	}

	for _, stmt := range stmts {
		var pathStr, valStr string
		if colorize {
			pathStr = formatPathColor(stmt.Path)
			valStr = formatValueColor(stmt.Value, stmt.ValType)
		} else {
			var buf bytes.Buffer
			for i, t := range stmt.Path {
				buf.WriteString(formatTokenString(t, i == 0))
			}
			pathStr = buf.String()
			valStr = stmt.Value
		}
		fmt.Fprintf(w, "%s = %s;\n", pathStr, valStr)
	}
	return nil
}
EOF
"}

