					obj = append(obj, Pair{Key: t.Key, Val: val})
				} else {
					obj[idx].Val = val
				}
			}
		} else {
			if idx == -1 {
				var child interface{}
				if path[1].IsIndex {
					child = []interface{}{}
				} else {
					child = Object{}
				}
				err := mergeNode(&child, path[1:], val)
				if err != nil {
					return err
				}
				obj = append(obj, Pair{Key: t.Key, Val: child})
			} else {
