		val = Object{}
	} else if rhs == "[]" {
		val = []interface{}{}
	} else {
		err := json.Unmarshal([]byte(rhs), &val)
		if err != nil {
			return nil, nil, fmt.Errorf("invalid value `%s`", rhs)
		}
	}

	return tokens, val, nil
}

func parsePathLHS(lhs string) ([]Token, error) {
	if lhs == "" {
		return nil, fmt.Errorf("invalid statement")
	}

	var tokens []Token
	i := 0
	n := len(lhs)

	// First token
	if lhs[0] == '[' {
		tok, nextI, err := parseBracketToken(lhs, 0)
		if err != nil {
			return nil, fmt.Errorf("invalid statement")
		}
		tokens = append(tokens, tok)
		i = nextI
	} else {
		start := i
		for i < n && isAlphaChar(rune(lhs[i])) {
			i++
		}
		if i == start {
			return nil, fmt.Errorf("invalid statement")
		}
		tokKey := lhs[start:i]
		if !validIdentifier(tokKey) && tokKey != "json" {
			return nil, fmt.Errorf("invalid statement")
		}
		tokens = append(tokens, Token{Key: tokKey, IsIndex: false})
	}

	for i < n {
		if lhs[i] == '.' {
			i++
			start := i
			for i < n && isAlphaChar(rune(lhs[i])) {
				i++
			}
			if i == start {
				return nil, fmt.Errorf("invalid statement")
			}
			tokKey := lhs[start:i]
			if !validIdentifier(tokKey) {
				return nil, fmt.Errorf("invalid statement")
			}
			tokens = append(tokens, Token{Key: tokKey, IsIndex: false})
		} else if lhs[i] == '[' {
			tok, nextI, err := parseBracketToken(lhs, i)
			if err != nil {
				return nil, fmt.Errorf("invalid statement")
			}
			tokens = append(tokens, tok)
			i = nextI
		} else {
			return nil, fmt.Errorf("invalid statement")
		}
	}

	return tokens, nil
}

func parseBracketToken(s string, start int) (Token, int, error) {
	if start >= len(s) || s[start] != '[' {
		return Token{}, start, fmt.Errorf("expected [")
	}
	i := start + 1
	if i >= len(s) {
		return Token{}, start, fmt.Errorf("unclosed [")
	}

	if s[i] == '"' {
		strStart := i
		i++
		for i < len(s) {
			if s[i] == '\\' && i+1 < len(s) {
				i += 2
				continue
			}
			if s[i] == '"' {
				i++
				break
			}
			i++
		}
		if i > len(s) || s[i-1] != '"' {
			return Token{}, start, fmt.Errorf("unclosed string key")
		}
		var keyStr string
		err := json.Unmarshal([]byte(s[strStart:i]), &keyStr)
		if err != nil {
			return Token{}, start, err
		}
		if i >= len(s) || s[i] != ']' {
			return Token{}, start, fmt.Errorf("expected ]")
		}
		return Token{Key: keyStr, IsIndex: false}, i + 1, nil
	} else {
		numStart := i
		for i < len(s) && unicode.IsDigit(rune(s[i])) {
			i++
		}
		if i == numStart {
			return Token{}, start, fmt.Errorf("expected digits")
		}
		idx, err := strconv.Atoi(s[numStart:i])
		if err != nil {
			return Token{}, start, err
		}
		if i >= len(s) || s[i] != ']' {
			return Token{}, start, fmt.Errorf("expected ]")
		}
		return Token{Index: idx, IsIndex: true}, i + 1, nil
	}
}

func ProcessValues(r io.Reader, w io.Writer) error {
	scanner := bufio.NewScanner(r)
	for scanner.Scan() {
		line := scanner.Text()
		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			continue
		}
		_, val, err := parseGronLine(line)
		if err != nil {
			continue
		}
		if val == nil {
			continue
		}
		switch v := val.(type) {
		case Object:
		case []interface{}:
			if len(v) > 0 {
				b, _ := jsonMarshal(v)
				fmt.Fprintln(w, string(b))
			}
		case string:
			fmt.Fprintln(w, v)
		case bool:
			if v {
				fmt.Fprintln(w, "true")
			} else {
				fmt.Fprintln(w, "false")
			}
		case json.Number:
			fmt.Fprintln(w, string(v))
		case float64:
			b, _ := jsonMarshal(v)
			fmt.Fprintln(w, string(b))
		default:
			if v == nil {
				fmt.Fprintln(w, "null")
			} else {
				b, _ := jsonMarshal(v)
				fmt.Fprintln(w, string(b))
			}
		}
	}
	return nil
}

func ProcessUngron(r io.Reader, w io.Writer, isJSON, colorize bool) error {
	var root interface{}
	hasRoot := false

	if isJSON {
		dec := json.NewDecoder(r)
		for {
			var raw []interface{}
			err := dec.Decode(&raw)
			if err != nil {
				if err == io.EOF {
					break
				}
				return fmt.Errorf("failed to parse statements: %w", err)
			}
			if len(raw) != 2 {
				return fmt.Errorf("failed to parse statements: invalid json stream statement")
			}
			pathRaw, ok := raw[0].([]interface{})
			if !ok {
				return fmt.Errorf("failed to parse statements: invalid path array")
			}
			val := raw[1]

			var tokens []Token
			tokens = append(tokens, Token{Key: "json", IsIndex: false})
			for _, elem := range pathRaw {
				if k, ok := elem.(string); ok {
					tokens = append(tokens, Token{Key: k, IsIndex: false})
				} else if n, ok := elem.(float64); ok {
					tokens = append(tokens, Token{Index: int(n), IsIndex: true})
				} else if num, ok := elem.(json.Number); ok {
					i, _ := num.Int64()
					tokens = append(tokens, Token{Index: int(i), IsIndex: true})
				}
			}

			err = mergeStatement(&root, tokens, val, &hasRoot)
			if err != nil {
				return err
			}
		}
	} else {
		scanner := bufio.NewScanner(r)
		parsedCount := 0
		for scanner.Scan() {
			line := scanner.Text()
			if strings.TrimSpace(line) == "" {
				continue
			}
			tokens, val, err := parseGronLine(line)
			if err != nil {
				return fmt.Errorf("ungron failed for `%s`: %w", strings.TrimSpace(line), err)
			}
			if tokens == nil {
				continue
			}
			parsedCount++
			err = mergeStatement(&root, tokens, val, &hasRoot)
			if err != nil {
				return err
			}
		}
		if parsedCount == 0 {
			return fmt.Errorf("no statements were parsed")
		}
	}

	if !hasRoot {
		return fmt.Errorf("no statements were parsed")
	}

	var jsonBytes []byte
	var err error

	if colorize {
		if root == nil {
			jsonBytes = []byte("null")
		} else {
			jsonBytes, err = jsonMarshal(root)
			if err != nil {
				return fmt.Errorf("failed to encode JSON: %w", err)
			}
		}
		jsonBytes = colorizeJSON(jsonBytes)
	} else {
		if root == nil {
			jsonBytes = []byte("null")
		} else {
			jsonBytes, err = json.MarshalIndent(root, "", "  ")
			if err != nil {
				return fmt.Errorf("failed to encode JSON: %w", err)
			}
		}
	}

	fmt.Fprintln(w, string(jsonBytes))
	return nil
}

func mergeStatement(root *interface{}, tokens []Token, val interface{}, hasRoot *bool) error {
	*hasRoot = true

	path := tokens
	if len(path) > 0 && path[0].Key == "json" && !path[0].IsIndex {
		if len(path) > 1 {
			path = path[1:]
		} else {
			if *root == nil {
				*root = val
			} else {
				if _, ok := val.(Object); ok {
				} else if _, ok := val.([]interface{}); ok {
				} else {
					*root = val
				}
			}
			return nil
		}
	}

	return mergeNode(root, path, val)
}

func mergeNode(target *interface{}, path []Token, val interface{}) error {
	if len(path) == 0 {
		*target = val
		return nil
	}

	t := path[0]

	if t.IsIndex {
		if *target == nil {
			*target = []interface{}{}
		}
		arr, ok := (*target).([]interface{})
		if !ok {
			return fmt.Errorf("failed to merge statements: cannot merge array with non-array")
		}
		for len(arr) <= t.Index {
			arr = append(arr, nil)
		}
		if len(path) == 1 {
			if _, isObj := val.(Object); isObj {
				if arr[t.Index] == nil {
					arr[t.Index] = Object{}
				}
			} else if _, isArr := val.([]interface{}); isArr {
				if arr[t.Index] == nil {
					arr[t.Index] = []interface{}{}
				}
			} else {
				arr[t.Index] = val
			}
		} else {
			if arr[t.Index] == nil {
				if path[1].IsIndex {
					arr[t.Index] = []interface{}{}
				} else {
					arr[t.Index] = Object{}
				}
			}
			err := mergeNode(&arr[t.Index], path[1:], val)
			if err != nil {
				return err
			}
		}
		*target = arr
		return nil
	} else {
		if *target == nil {
			*target = Object{}
		}
		var obj Object
		if o, ok := (*target).(Object); ok {
			obj = o
		} else if _, ok := (*target).([]interface{}); ok {
			return fmt.Errorf("failed to merge statements: cannot merge array with non-array")
		} else if m, ok := (*target).(map[string]interface{}); ok {
			for k, v := range m {
				obj = append(obj, Pair{Key: k, Val: v})
			}
		} else {
			return fmt.Errorf("failed to merge statements: cannot merge object with non-object")
		}

		idx := -1
		for i, p := range obj {
			if p.Key == t.Key {
				idx = i
				break
			}
		}

		if len(path) == 1 {
			if _, isObj := val.(Object); isObj {
				if idx == -1 {
					obj = append(obj, Pair{Key: t.Key, Val: Object{}})
				}
			} else if _, isArr := val.([]interface{}); isArr {
				if idx == -1 {
					obj = append(obj, Pair{Key: t.Key, Val: []interface{}{}})
				}
			} else {
				if idx == -1 {
					obj = append(obj, Pair{Key: t.Key, Val: val})
				} else {
					obj[idx].Val = val
				}
			}
		} else {
			if idx == -1 {
				var child interface{}
				if path[1].IsIndex {
					child = []interface{}{}
				} else {
					child = Object{}
				}
				err := mergeNode(&child, path[1:], val)
				if err != nil {
					return err
				}
				obj = append(obj, Pair{Key: t.Key, Val: child})
			} else {
				err := mergeNode(&obj[idx].Val, path[1:], val)
				if err != nil {
					return err
				}
			}
		}
		*target = obj
		return nil
	}
}

func (o Object) MarshalJSON() ([]byte, error) {
	var buf bytes.Buffer
	buf.WriteByte('{')
	for i, pair := range o {
		if i > 0 {
			buf.WriteByte(',')
		}
		keyBytes, err := jsonMarshal(pair.Key)
		if err != nil {
			return nil, err
		}
		buf.Write(keyBytes)
		buf.WriteByte(':')
		valBytes, err := jsonMarshal(pair.Val)
		if err != nil {
			return nil, err
		}
		buf.Write(valBytes)
	}
	buf.WriteByte('}')
	return buf.Bytes(), nil
}
EOF
"}

{"command":"cat << 'EOF' > main.go
package main

import (
	"crypto/tls"
	"flag"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"strings"
	"syscall"
	"unsafe"
)

const versionString = "gron version dev"

const helpText = `Transform JSON (from a file, URL, or stdin) into discrete assignments to make it greppable

Usage:
  gron [OPTIONS] [FILE|URL|-]

Options:
  -u, --ungron     Reverse the operation (turn assignments back into JSON)
  -v, --values     Print just the values of provided assignments
  -c, --colorize   Colorize output (default on tty)
  -m, --monochrome Monochrome (don't colorize output)
  -s, --stream     Treat each line of input as a separate JSON object
  -k, --insecure   Disable certificate validation
  -x, --proxy      Set proxy configuration
      --noproxy    Comma-separated list of hosts for which not to use a proxy, if one is specified.
  -j, --json       Represent gron data as JSON stream
      --no-sort    Don't sort output (faster)
      --version    Print version information

Exit Codes:
  0	OK
  1	Failed to open file
  2	Failed to read input
  3	Failed to form statements
  4	Failed to fetch URL
  5	Failed to parse statements
  6	Failed to encode JSON

Examples:
  gron /tmp/apiresponse.json
  gron http://jsonplaceholder.typicode.com/users/1 
  curl -s http://jsonplaceholder.typicode.com/users/1 | gron
  gron http://jsonplaceholder.typicode.com/users/1 | grep company | gron --ungron
`

func isTTY(f *os.File) bool {
	var termios syscall.Termios
	_, _, err := syscall.Syscall6(syscall.SYS_IOCTL, f.Fd(), uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&termios)), 0, 0, 0)
	return err == 0
}

func main() {
	flags := flag.NewFlagSet("gron", flag.ContinueOnError)
	flags.SetOutput(os.Stderr)
	flags.Usage = func() {}

	ungron := flags.Bool("u", false, "")
	flags.BoolVar(ungron, "ungron", false, "")

	values := flags.Bool("v", false, "")
	flags.BoolVar(values, "values", false, "")

	colorize := flags.Bool("c", false, "")
	flags.BoolVar(colorize, "colorize", false, "")

	monochrome := flags.Bool("m", false, "")
	flags.BoolVar(monochrome, "monochrome", false, "")

	stream := flags.Bool("s", false, "")
	flags.BoolVar(stream, "stream", false, "")

	insecure := flags.Bool("k", false, "")
	flags.BoolVar(insecure, "insecure", false, "")

	proxy := flags.String("x", "", "")
	flags.StringVar(proxy, "proxy", "", "")

	noProxy := flags.String("noproxy", "", "")

	jsonStream := flags.Bool("j", false, "")
	flags.BoolVar(jsonStream, "json", false, "")

	noSort := flags.Bool("no-sort", false, "")

	versionFlag := flags.Bool("version", false, "")

	err := flags.Parse(os.Args[1:])
	if err != nil {
		if err == flag.ErrHelp {
			fmt.Fprint(os.Stderr, helpText)
			os.Exit(0)
		}
		fmt.Fprint(os.Stderr, helpText)
		os.Exit(2)
	}

	if *versionFlag {
		fmt.Println(versionString)
		os.Exit(0)
	}

	useColor := false
	if *colorize {
		useColor = true
	} else if *monochrome {
		useColor = false
	} else {
		useColor = isTTY(os.Stdout)
	}

	var r io.Reader
	var closeInput func()
	args := flags.Args()
	inputLocation := "-"
	if len(args) > 0 {
		inputLocation = args[0]
	}

	if inputLocation == "-" {
		r = os.Stdin
		closeInput = func() {}
	} else if strings.HasPrefix(inputLocation, "http://") || strings.HasPrefix(inputLocation, "https://") {
		req, err := http.NewRequest("GET", inputLocation, nil)
		if err != nil {
			fmt.Fprintf(os.Stderr, "%s\n", err)
			os.Exit(4)
		}
		req.Header.Set("User-Agent", "gron/dev")
		req.Header.Set("Accept", "application/json")

		tr := &http.Transport{}
		if *insecure {
			tr.TLSClientConfig = &tls.Config{InsecureSkipVerify: true}
		}

		proxyVal := *proxy
		noProxyVal := *noProxy
		if proxyVal != "" || noProxyVal != "" {
			tr.Proxy = func(req *http.Request) (*url.URL, error) {
				if noProxyVal != "" {
					hosts := strings.Split(noProxyVal, ",")
					reqHost := req.URL.Hostname()
					for _, h := range hosts {
						h = strings.TrimSpace(h)
						if h != "" && (reqHost == h || strings.HasSuffix(reqHost, "."+h)) {
							return nil, nil
						}
					}
				}
				if proxyVal != "" {
					u, err := url.Parse(proxyVal)
					if err != nil {
						return nil, err
					}
					return u, nil
				}
				return http.ProxyFromEnvironment(req)
			}
		} else {
			tr.Proxy = http.ProxyFromEnvironment
		}

		client := &http.Client{Transport: tr}
		resp, err := client.Do(req)
		if err != nil {
			fmt.Fprintf(os.Stderr, "%s\n", err)
			os.Exit(4)
		}
		r = resp.Body
		closeInput = func() { resp.Body.Close() }
	} else {
		f, err := os.Open(inputLocation)
		if err != nil {
			fmt.Fprintf(os.Stderr, "%s\n", err)
			os.Exit(1)
		}
		r = f
		closeInput = func() { f.Close() }
	}
	defer closeInput()

	if *values {
		err := ProcessValues(r, os.Stdout)
		if err != nil {
			fmt.Fprintf(os.Stderr, "%s\n", err)
			os.Exit(5)
		}
		os.Exit(0)
	}

	if *ungron {
		err := ProcessUngron(r, os.Stdout, *jsonStream, useColor)
		if err != nil {
			fmt.Fprintf(os.Stderr, "%s\n", err)
			os.Exit(5)
		}
		os.Exit(0)
	}

	err = ProcessGron(r, os.Stdout, *stream, *jsonStream, *noSort, useColor)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s\n", err)
		if strings.Contains(err.Error(), "failed to encode JSON") {
			os.Exit(6)
		}
		os.Exit(3)
	}
	os.Exit(0)
}
EOF
"}

