func naturalLess(s1, s2 string) bool {
	c1 := chunkString(s1)
	c2 := chunkString(s2)

	min := len(c1)
	if len(c2) < min {
		min = len(c2)
	}

	for i := 0; i < min; i++ {
		if c1[i].isNum && c2[i].isNum {
